      const prev = idx > 0 ? series[idx-1] : null;
      let line = `${formatIsoUtc(r.ts)}  reading=${formatKwh(r.milli)} kWh`;
      if (!prev) line += '  interval=n/a  consumption=n/a (no predecessor)';
      else {
        const diff = r.milli - prev.milli;
        const dur = r.ts - prev.ts;
        line += `  interval=${formatIsoUtc(prev.ts)}..${formatIsoUtc(r.ts)} (${dur}s)`;
