    err(`import rejected: ${conflicts.length} conflict(s); nothing was imported`);
    return 1;
  }

  try {
    saveStore(storePath, existing.concat(toAdd));
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
